        serverMap.put("a", server(30001));
        serverMap.put("b", server(30002));
        String r = handler.telnet(null, "");
        assertTrue(r.contains("30001"));
        assertTrue(r.contains("30002"));
        assertTrue(r.contains("\r\n"));
    }

