        assertTrue(r.contains("dubbo://127.0.0.1:30001"));
        assertTrue(r.contains("dubbo://127.0.0.1:30002"));
        assertTrue(r.contains("\r\n"));
    }

    @Test
    public void testNoSuchPort() {
        serverMap.put("a", server(30001));
